<script setup>
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { forecastPresentation, forecastMetricSummary, forecastPresentationCsv, forecastDate } from './eclipseForecastPresentation.js'
import { exportEclipseCharts } from './eclipseChartExport.js'
const fmt = value => Number.isFinite(value) ? value.toLocaleString('zh-CN', { maximumFractionDigits: 6 }) : '未提供'
const props = defineProps({ kind: String, source: Object, catalog: Object, history: Object, run: Object, other: Object, inspection: Object, portable: Boolean })
const emit = defineEmits(['select-run'])
const model = computed(() => forecastPresentation(props)), metricKey = ref(''), mode = ref('actual'), reportNumber = ref(null), host = ref(null)
const selected = computed(() => model.value.metrics.find(m => m.key === metricKey.value) || model.value.metrics.find(m => m.keyword === 'FOPT') || model.value.metrics[0])
const summary = computed(() => forecastMetricSummary(selected.value))
const inspectedReport = computed(() => model.value.reports.find(r => r.reportNumber === reportNumber.value) || model.value.reports.find(r => r.reportNumber === model.value.report))
watch([() => props.run?.id, () => props.other?.id, () => props.history?.id], () => { metricKey.value = ''; mode.value = 'actual'; reportNumber.value = null })
watch(metricKey, () => { mode.value = 'actual' })
let chart, observer, generation = 0
async function render() {
  const token = ++generation; await nextTick(); if (token !== generation) return
  if (!host.value || !model.value.valid || !selected.value) { observer?.disconnect(); chart?.dispose(); chart = null; return }
  if (!chart || chart.getDom() !== host.value) { observer?.disconnect(); chart?.dispose(); chart = echarts.init(host.value); observer = new ResizeObserver(() => chart?.resize()); observer.observe(host.value) }
  const m = selected.value, increment = mode.value === 'increment' && m.cumulative && m.savedValue != null
  const series = [], colors = ['#287fc2','#169c95']
  if (!increment && m.historical.length) series.push({ name: `保存点前历史 #${model.value.historyId}`, type: 'line', showSymbol: false, lineStyle: { type: 'dashed', width: 2 }, itemStyle: { color: '#8fa5ba' }, data: m.historical.map(p => [p.timeDays,p.value]) })
  m.forecasts.forEach((f,i) => series.push({ name: `预测 #${f.runId} · ${f.label}`, type: 'line', showSymbol: true, symbolSize: 4, lineStyle: { width: 2.5 }, itemStyle: { color: colors[i] }, data: f.points.map(p => [p.timeDays,increment ? p.value-m.savedValue : p.value]) }))
  if (series.length) series[0].markLine = { symbol: 'none', label: { formatter: `保存点 · 第${model.value.cutoff}天`, color: '#a98345', fontSize: 10 }, lineStyle: { type: 'dashed', color: '#d1a252' }, data: [{ xAxis: model.value.cutoff }] }
  chart.setOption({ animation: false, title: { text: `${m.keyword} · ${m.objectName || '全场'}${m.vectorIndex == null ? '' : ` · 原始列${m.vectorIndex+1}`} · ${increment ? '保存点后新增' : '原始计算值'}`, subtext: `${model.value.sourceFile} · ${m.unit} · 保存报告 ${model.value.report} / 第 ${model.value.cutoff} 天`, left: 12, top: 10, textStyle: { fontSize: 12, color: '#2c5271' }, subtextStyle: { fontSize: 10 } }, legend: { type: 'scroll', top: 57, textStyle: { fontSize: 10 }, left: 14, right: 14 }, tooltip: { trigger: 'axis', renderMode: 'richText' }, grid: { left: 18, right: 35, top: 100, bottom: 50, containLabel: true }, xAxis: { type: 'value', name: '原起算日期后的实际天数', nameLocation: 'middle', nameGap: 29, splitLine: { show: false } }, yAxis: { type: 'value', scale: true, splitLine: { lineStyle: { color: '#edf3f8' } } }, dataZoom: [{ type: 'inside' }], series }, true)
  chart.resize()
}
watch([model, selected, mode], render, { immediate: true })
onBeforeUnmount(() => { generation++; observer?.disconnect(); chart?.dispose() })
const exportPng = () => chart && exportEclipseCharts([chart],`eclipse-forecast-${props.run.id}-${selected.value.keyword}-${selected.value.vectorIndex ?? 'single'}-${mode.value}.png`)
function exportCsv() { const url = URL.createObjectURL(new Blob([forecastPresentationCsv(model.value)], { type: 'text/csv;charset=utf-8' })), a = document.createElement('a'); a.href = url; a.download = `eclipse-forecast-${props.run.id}-branches.csv`; a.click(); setTimeout(() => URL.revokeObjectURL(url),1000) }
</script>
<template>
  <section class="forecast-dashboard" aria-label="ECLIPSE保存点与预测分支看板" :data-ready="model.valid ? 'true':'false'" :data-run-id="run?.id" :data-other-id="other?.id || ''">
    <el-alert v-if="!model.valid" type="info" :closable="false" :title="model.reason"/>
    <template v-else>
      <header><div><span>HISTORY → SAVEPOINT → FORECAST</span><h3>从同一历史状态，看未来方案怎样分叉</h3><p>{{ model.sourceFile }} · 原起算 {{ model.startDate }} · {{ model.kind === 'e300' ? 'E300组分' : 'E100' }}</p></div><el-tag type="success">保存点来源已核对</el-tag></header>
      <div class="forecast-flow"><article class="history-node"><small>{{ model.historyId ? `历史运行 #${model.historyId}` : '完整工程内的历史状态' }}</small><strong>{{ model.startDate }}</strong><span>保留原起算日期</span></article><span class="flow-arrow">→</span><article class="save-node"><small>保存报告 {{ model.report }}</small><strong>第 {{ model.cutoff }} 天</strong><span>{{ forecastDate(model.startDate,model.cutoff) }}</span></article><span class="flow-arrow">↗</span><div class="forecast-branches"><button v-for="f in model.forecasts" :key="f.id" type="button" :class="{current:f.id===run.id}" @click="emit('select-run',f.id)"><b>预测 #{{f.id}} · {{f.label}}</b><span>首个输出 {{f.firstDays}} 天 → {{f.lastDays}} 天 · {{f.actualTimes}}个实际时刻</span></button><div v-if="!model.forecasts.length" class="future-empty">选择下方续算操作，创建自己的预测分支</div></div></div>
      <div class="save-reports"><label>查看已保存报告 <el-select v-model="reportNumber" aria-label="查看历史保存报告" :placeholder="`报告 ${model.report}`"><el-option v-for="r in model.reports" :key="r.reportNumber" :value="r.reportNumber" :label="`报告 ${r.reportNumber} · 第${r.timeDays}天 · ${r.date}`"/></el-select></label><span v-if="inspectedReport">第 {{inspectedReport.timeDays}} 天 · {{inspectedReport.date}} · {{inspectedReport.predictable ? '有已支持的预测入口' : '已保存状态，当前没有对应预测输入' }}</span></div>
      <p class="note">报告选择仅查看已存在的状态；当前预测仍从报告{{model.report}}开始。首个未来输出按原生实际时刻显示，不补造保存点处的预测值。</p>
      <div class="forecast-kpis" aria-label="保存点与预测增量指标"><article><small>保存点 {{selected.keyword}} · {{selected.objectName||'全场'}}</small><strong>{{selected.savedValue==null ? '未提供':fmt(selected.savedValue)}}</strong><span>{{selected.unit}} · 第{{model.cutoff}}天实际值</span></article><article v-for="f in summary.entries" :key="f.runId"><small>预测 #{{f.runId}} · {{f.increment==null ? '末报告值':'保存点后新增'}}</small><strong>{{fmt(f.increment==null ? f.last.value:f.increment)}}</strong><span>{{selected.unit}} · 第{{f.last.timeDays}}天{{f.increment==null ? '' : ` · 末累计 ${fmt(f.last.value)}`}}</span></article><article v-if="summary.common"><small>共同实际时刻 · 当前 − 对比</small><strong>{{fmt(summary.common.difference)}}</strong><span>{{selected.unit}} · 第{{summary.common.timeDays}}天</span></article></div>
      <div class="forecast-controls"><el-select v-model="metricKey" aria-label="预测分支指标" :placeholder="`${selected.keyword} · ${selected.objectName||'全场'}`"><el-option v-for="m in model.metrics" :key="m.key" :value="m.key" :label="`${m.keyword} · ${m.objectName||'全场'}${m.vectorIndex==null ? '' : ` · 原始列${m.vectorIndex+1}`} · ${m.unit}`"/></el-select><el-radio-group v-if="selected.cumulative && selected.savedValue!=null && model.forecasts.length" v-model="mode" aria-label="预测曲线数值方式"><el-radio-button value="actual">累计原值</el-radio-button><el-radio-button value="increment">保存点后新增</el-radio-button></el-radio-group><el-button size="small" @click="exportPng">导出预测分支PNG</el-button><el-button size="small" @click="exportCsv">导出接续指标CSV</el-button></div>
      <div ref="host" class="forecast-chart" role="img" aria-label="历史与独立预测分支实际曲线"/>
      <p class="note">同名列分别保留；两方案差值取最后一个共同实际输出时刻，新增量只在有保存点实际累计值时相减。缺少历史累计的导入工程只显示预测原值。曲线不插值，正负差值不自动代表收益或优劣。</p>
    </template>
  </section>
</template>
<style scoped>
.forecast-dashboard { margin:20px 0;padding:22px;border:1px solid #dce6f0;border-radius:13px;background:linear-gradient(130deg,#f0f6ff,#fff 65%);color:#59778f;min-width:0 }.forecast-dashboard header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:start}.forecast-dashboard header span{font-size:10px;letter-spacing:.1em;color:#4a84b0;font-weight:700}.forecast-dashboard h3{font-size:19px;color:#264c6c;margin:8px 0}.forecast-dashboard p{font-size:11px;line-height:1.8}.forecast-flow{display:flex;align-items:center;gap:12px;margin:24px 0;overflow-x:auto;padding:3px}.forecast-flow>article{padding:18px;border:1px solid #d8e5f0;border-radius:10px;background:#fff;min-width:160px}.forecast-flow small,.forecast-flow span,.forecast-branches span{display:block;font-size:10px;color:#8196a8}.forecast-flow strong{display:block;font-size:19px;color:#365d7a;margin:12px 0}.forecast-flow .save-node{border-color:#ccab6c;background:#fffaf0}.forecast-flow .save-node strong{color:#ab7c36}.flow-arrow{font-size:24px!important;color:#abc2d5!important}.forecast-branches{flex:1;display:grid;gap:10px;min-width:290px}.forecast-branches button{padding:15px;text-align:left;border:1px solid #b5d9d5;border-radius:9px;background:#f0faf8;color:#2c817b;cursor:pointer}.forecast-branches button.current{border-color:#87b7dd;background:#edf6ff;color:#3179ae}.forecast-branches b{display:block;font-size:12px;margin-bottom:9px}.save-reports{display:flex;gap:16px;align-items:center;flex-wrap:wrap;font-size:11px}.save-reports label{display:flex;align-items:center;gap:10px}.save-reports .el-select{width:300px}.forecast-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin:18px 0}.forecast-kpis article{background:#fff;border:1px solid #dce7ef;border-radius:9px;padding:17px;min-width:0}.forecast-kpis small,.forecast-kpis span{display:block;font-size:10px;color:#8395a7}.forecast-kpis strong{display:block;font-size:25px;color:#2d6086;margin:12px 0;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.forecast-controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.forecast-controls>.el-select{width:min(400px,100%)}.forecast-controls .el-button{margin:0}.forecast-chart{height:370px;margin-top:16px;border:1px solid #e1e9f2;border-radius:9px;background:#fff}.note{color:#8b9bac}.future-empty{background:#eef3f8;padding:24px;border-radius:9px;font-size:12px}@media(max-width:650px){.forecast-dashboard{padding:12px}.forecast-flow{align-items:stretch;flex-direction:column;overflow:visible}.flow-arrow{align-self:center;transform:rotate(90deg)}.forecast-branches{min-width:0}.save-reports label{display:block;width:100%}.save-reports .el-select{width:100%;margin-top:8px}.forecast-kpis strong{font-size:20px}.forecast-dashboard h3{font-size:16px}}
</style>
